# -*- coding: utf-8 -*-
"""
PrintAgent Windows GUI Installer
Modern Windows App Installer style with real-time progress and English UI.
"""

import os
import sys
import shutil
import time
import json
import threading
import subprocess
import urllib.request
import ssl
import ctypes
from pathlib import Path
import tkinter as tk
from tkinter import ttk

LOGO_PNG_BASE64 = """"""

INSTALL_DIR = Path(os.environ.get("APPDATA", "")) / "GoxPrintAgent"

def log_install(msg: str) -> None:
    try:
        temp_dir = os.environ.get("TEMP")
        if temp_dir:
            log_file = Path(temp_dir) / "printagent_installer.log"
            with open(log_file, "a", encoding="utf-8") as f:
                f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {msg}\n")
                f.flush()
    except Exception:
        pass

def get_api_url_from_settings() -> str:
    dirs_to_check = []
    try:
        dirs_to_check.append(Path(sys.executable).parent)
    except Exception:
        pass
    dirs_to_check.append(Path("."))
    dirs_to_check.append(INSTALL_DIR)
    
    for d in dirs_to_check:
        settings_path = d / "settings.json"
        if settings_path.exists():
            try:
                with settings_path.open("r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    api_url = data.get("api_url") or data.get("polling", {}).get("url")
                    if api_url:
                        log_install(f"Read API URL from: {settings_path} -> {api_url}")
                        return api_url.strip()
            except Exception:
                pass
    return "https://agentapi.quanlymay.com"

def kill_existing_processes() -> None:
    log_install("Terminating lingering processes and cleaning old update files...")
    try:
        import glob
        for update_file in glob.glob(str(INSTALL_DIR / "*.update.exe")) + glob.glob(str(INSTALL_DIR / "*.bak.exe")):
            try:
                os.remove(update_file)
            except Exception:
                pass
        for old_file in ["update_notice.json", "version.txt", "watchdog.bat", "run_watchdog.vbs"]:
            try:
                (INSTALL_DIR / old_file).unlink(missing_ok=True)
            except Exception:
                pass
    except Exception as e:
        log_install(f"Error cleaning files: {e}")

    _NO_WIN = 0x08000000
    try:
        subprocess.run(["taskkill", "/F", "/T", "/IM", "printagent.exe"], capture_output=True, creationflags=_NO_WIN)
        subprocess.run(["taskkill", "/F", "/T", "/IM", "agent_loader.exe"], capture_output=True, creationflags=_NO_WIN)
        subprocess.run(["wmic", "process", "where", "name='cmd.exe' and commandline like '%watchdog.bat%'", "call", "terminate"], capture_output=True, creationflags=_NO_WIN)
        subprocess.run(["wmic", "process", "where", "name='wscript.exe' and commandline like '%run_watchdog.vbs%'", "call", "terminate"], capture_output=True, creationflags=_NO_WIN)
    except Exception:
        pass
    time.sleep(1.0)

    try:
        old_exe = INSTALL_DIR / "printagent.exe"
        bak_exe = INSTALL_DIR / "printagent.old.exe"
        if old_exe.exists():
            if bak_exe.exists():
                bak_exe.unlink()
            old_exe.rename(bak_exe)
    except Exception:
        pass

    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Run", 0, winreg.KEY_ALL_ACCESS) as key:
            for old_key in ["GoPrinxAgent", "GoPrinxAgentFtpWorker", "GoPrinxAgentMain"]:
                try:
                    winreg.DeleteValue(key, old_key)
                except Exception:
                    pass
    except Exception:
        pass

def download_binary(dest_path: Path, api_url: str, binary_name: str, progress_cb=None) -> bool:
    log_install(f"Downloading {binary_name}...")
    base_url = api_url.strip().rstrip("/")
    if base_url.endswith("/api"):
        base_url = base_url[:-4]

    cache_buster = f"t={int(time.time() * 1000)}"
    download_url = f"{base_url}/static/releases/{binary_name}?{cache_buster}"

    ssl_ctx = ssl.create_default_context()
    ssl_ctx.check_hostname = False
    ssl_ctx.verify_mode = ssl.CERT_NONE

    candidate_urls = [
        download_url,
        f"https://download.goxprint.com/{binary_name}?{cache_buster}",
        f"https://agentapi.quanlymay.com/static/releases/{binary_name}?{cache_buster}",
    ]

    last_err = None
    for target_url in candidate_urls:
        req = urllib.request.Request(
            target_url,
            headers={
                "Cache-Control": "no-cache, no-store, must-revalidate, max-age=0",
                "Pragma": "no-cache",
                "Expires": "0",
                "User-Agent": "PrintAgentSetup/3.0"
            }
        )
        try:
            tmp_path = dest_path.with_suffix('.tmp')
            with urllib.request.urlopen(req, timeout=45, context=ssl_ctx) as response:
                total_size = int(response.headers.get('content-length', 0))
                block_size = 1024 * 64
                downloaded = 0

                with open(tmp_path, 'wb') as f:
                    while True:
                        buffer = response.read(block_size)
                        if not buffer:
                            break
                        downloaded += len(buffer)
                        f.write(buffer)
                        if progress_cb and total_size > 0:
                            progress_cb(downloaded, total_size)

                if dest_path.exists():
                    try:
                        old_path = dest_path.with_suffix('.old')
                        if old_path.exists():
                            old_path.unlink()
                        dest_path.rename(old_path)
                    except Exception:
                        try:
                            dest_path.unlink()
                        except Exception:
                            pass
                tmp_path.replace(dest_path)
                log_install(f"Downloaded {binary_name} successfully ({downloaded} bytes).")
                return True
        except Exception as e:
            last_err = e
            log_install(f"URL {target_url} failed: {e}")

    log_install(f"All download candidate URLs failed for {binary_name}. Last err: {last_err}")
    return False

def configure_settings_json() -> None:
    settings_path = INSTALL_DIR / "settings.json"
    data = {}
    if settings_path.exists():
        try:
            with open(settings_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            pass

    if not isinstance(data, dict):
        data = {}
    if "polling" not in data or not isinstance(data["polling"], dict):
        data["polling"] = {}

    data["polling"]["device_interval_seconds"] = 60
    data["polling"]["interval_seconds"] = 60

    try:
        with open(settings_path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        log_install("Updated settings.json polling intervals.")
    except Exception as e:
        log_install(f"Could not update settings.json: {e}")

def create_startup_shortcut(target_exe: Path) -> None:
    log_install("Setting up Windows startup shortcut...")
    startup_dir = Path(os.environ.get("APPDATA", "")) / "Microsoft" / "Windows" / "Start Menu" / "Programs" / "Startup"
    startup_dir.mkdir(parents=True, exist_ok=True)

    # Delete legacy watchdog shortcuts
    for old_lnk in ["GoxPrintAgent Watchdog.lnk", "GoxPrintAgent_Watchdog_Startup.bat"]:
        try:
            (startup_dir / old_lnk).unlink(missing_ok=True)
        except Exception:
            pass

    shortcut_path = startup_dir / "GoxPrintAgent.lnk"
    try:
        import win32com.client
        shell = win32com.client.Dispatch("WScript.Shell")
        shortcut = shell.CreateShortCut(str(shortcut_path))
        shortcut.Targetpath = str(target_exe)
        shortcut.Arguments = ""
        shortcut.WorkingDirectory = str(target_exe.parent)
        shortcut.IconLocation = str(target_exe)
        shortcut.save()
        log_install(f"Created startup shortcut at {shortcut_path}")
    except Exception:
        fallback_bat = startup_dir / "GoxPrintAgent_Startup.bat"
        try:
            with open(fallback_bat, "w", encoding="utf-8") as f:
                f.write("@echo off\n")
                f.write(f'cd /d "{target_exe.parent}"\n')
                f.write(f'start "" "{target_exe.name}"\n')
            log_install(f"Created fallback startup batch at {fallback_bat}")
        except Exception as e:
            log_install(f"Failed to create startup shortcut: {e}")

def setup_gox_driver_service(api_url: str) -> None:
    try:
        install_dir = Path(os.environ.get("ProgramData", "C:/ProgramData")) / "GoxDriverService"
        install_dir.mkdir(parents=True, exist_ok=True)
        gds_exe = install_dir / "GoxDriverService.exe"

        base_url = api_url.strip().rstrip("/")
        if base_url.endswith("/api"):
            base_url = base_url[:-4]

        download_url = f"{base_url}/static/releases/GoxDriverService.exe?t={int(time.time() * 1000)}"
        ssl_ctx = ssl.create_default_context()
        ssl_ctx.check_hostname = False
        ssl_ctx.verify_mode = ssl.CERT_NONE

        req = urllib.request.Request(
            download_url,
            headers={"User-Agent": "PrintAgentSetup/3.0", "Cache-Control": "no-cache"}
        )
        try:
            with urllib.request.urlopen(req, timeout=30, context=ssl_ctx) as resp:
                gds_exe.write_bytes(resp.read())
            log_install("Downloaded GoxDriverService.exe")
        except Exception as dl_err:
            log_install(f"GoxDriverService download skipped or failed: {dl_err}")
            return

        _NO_WIN = 0x08000000
        subprocess.run(["sc.exe", "stop", "GoxDriverService"], capture_output=True, creationflags=_NO_WIN)
        time.sleep(0.5)

        r_inst = subprocess.run([str(gds_exe), "install"], capture_output=True, creationflags=_NO_WIN)
        if r_inst.returncode != 0:
            subprocess.run([
                "sc.exe", "create", "GoxDriverService",
                f'binPath="{gds_exe}"', "start=", "auto", "obj=", "LocalSystem",
                'DisplayName="Gox Driver Service"'
            ], capture_output=True, creationflags=_NO_WIN)

        subprocess.run(["sc.exe", "failure", "GoxDriverService", "reset=", "86400", "actions=", "restart/5000/restart/10000/restart/30000"], capture_output=True, creationflags=_NO_WIN)
        subprocess.run(["sc.exe", "start", "GoxDriverService"], capture_output=True, creationflags=_NO_WIN)
        log_install("GoxDriverService installed and started.")
    except Exception as e:
        log_install(f"GoxDriverService setup error: {e}")


class InstallerApp:
    def __init__(self, root: tk.Tk):
        self.root = root
        self.root.title("PrintAgent Setup")
        self.root.geometry("540x350")
        self.root.configure(bg="#ffffff")
        self.root.resizable(False, False)

        # Center on screen
        self.root.update_idletasks()
        w, h = 540, 350
        x = (self.root.winfo_screenwidth() // 2) - (w // 2)
        y = (self.root.winfo_screenheight() // 2) - (h // 2)
        self.root.geometry(f"{w}x{h}+{x}+{y}")

        self.cancelled = False
        self.completed = False
        self.dest_exe = INSTALL_DIR / "printagent.exe"

        # Try setting taskbar icon
        try:
            ico_path = Path("scratch/logo1.ico")
            if not ico_path.exists():
                ico_path = Path(sys.executable).parent / "scratch" / "logo1.ico"
            if ico_path.exists():
                self.root.iconbitmap(str(ico_path))
        except Exception:
            pass

        self._build_ui()
        self.root.after(300, self.start_installation)

    def _build_ui(self):
        # 1. Top Section
        top_frame = tk.Frame(self.root, bg="#ffffff")
        top_frame.pack(fill="x", padx=30, pady=(24, 0))

        left_content = tk.Frame(top_frame, bg="#ffffff")
        left_content.pack(side="left", fill="both", expand=True)

        title_lbl = tk.Label(
            left_content,
            text="Install PrintAgent?",
            font=("Segoe UI", 18),
            fg="#1a1a1a",
            bg="#ffffff",
            anchor="w"
        )
        title_lbl.pack(fill="x")

        badge_frame = tk.Frame(left_content, bg="#ffffff")
        badge_frame.pack(fill="x", pady=(4, 6))

        trusted_lbl = tk.Label(
            badge_frame,
            text="🛡️  Trusted App",
            font=("Segoe UI", 9, "bold"),
            fg="#0078d4",
            bg="#ffffff",
            anchor="w"
        )
        trusted_lbl.pack(side="left")

        self.version_str = "2.9.0"
        self.pub_lbl = tk.Label(
            left_content,
            text=f"Publisher: Gox Print\nVersion: {self.version_str}",
            font=("Segoe UI", 9),
            fg="#595959",
            bg="#ffffff",
            justify="left",
            anchor="w"
        )
        self.pub_lbl.pack(fill="x", pady=(0, 10))

        cap_title = tk.Label(
            left_content,
            text="Capabilities:",
            font=("Segoe UI", 9, "bold"),
            fg="#262626",
            bg="#ffffff",
            anchor="w"
        )
        cap_title.pack(fill="x")

        cap_desc = tk.Label(
            left_content,
            text="• Uses system background resources\n• Connects and synchronizes network printers",
            font=("Segoe UI", 9),
            fg="#595959",
            bg="#ffffff",
            justify="left",
            anchor="w"
        )
        cap_desc.pack(fill="x", pady=(2, 0))

        # Logo display on Top-Right
        logo_container = tk.Frame(top_frame, bg="#f0f7ff", width=76, height=76, highlightbackground="#d0e2ff", highlightthickness=1)
        logo_container.pack(side="right", anchor="n", padx=(10, 0))
        logo_container.pack_propagate(False)

        try:
            self.logo_img = tk.PhotoImage(data=LOGO_PNG_BASE64).subsample(4, 4)
            logo_lbl = tk.Label(logo_container, image=self.logo_img, bg="#f0f7ff")
            logo_lbl.pack(expand=True, fill="both")
        except Exception:
            logo_lbl = tk.Label(logo_container, text="🖨️", font=("Segoe UI Emoji", 30), bg="#f0f7ff", fg="#0078d4")
            logo_lbl.pack(expand=True, fill="both")

        # 2. Middle Section (Progress)
        mid_frame = tk.Frame(self.root, bg="#ffffff")
        mid_frame.pack(fill="x", padx=30, pady=(24, 0))

        self.status_var = tk.StringVar(value="Preparing installation...")
        self.status_lbl = tk.Label(
            mid_frame,
            textvariable=self.status_var,
            font=("Segoe UI", 9),
            fg="#262626",
            bg="#ffffff",
            anchor="w"
        )
        self.status_lbl.pack(fill="x", pady=(0, 6))

        style = ttk.Style()
        style.theme_use("clam")
        style.configure(
            "Custom.Horizontal.TProgressbar",
            troughcolor="#e6e6e6",
            background="#0078d4",
            thickness=8,
            bordercolor="#e6e6e6",
            lightcolor="#0078d4",
            darkcolor="#0078d4"
        )

        self.pbar = ttk.Progressbar(
            mid_frame,
            style="Custom.Horizontal.TProgressbar",
            orient="horizontal",
            length=480,
            mode="determinate"
        )
        self.pbar.pack(fill="x")
        self.pbar["value"] = 5

        # 3. Bottom Section (Controls)
        bot_frame = tk.Frame(self.root, bg="#ffffff")
        bot_frame.pack(fill="x", side="bottom", padx=30, pady=(0, 20))

        self.launch_var = tk.BooleanVar(value=True)
        chk_launch = tk.Checkbutton(
            bot_frame,
            text="Launch when ready",
            variable=self.launch_var,
            font=("Segoe UI", 9),
            fg="#262626",
            bg="#ffffff",
            activebackground="#ffffff",
            activeforeground="#262626",
            selectcolor="#ffffff",
            bd=0,
            highlightthickness=0
        )
        chk_launch.pack(side="left")

        self.btn_action = tk.Button(
            bot_frame,
            text="Cancel",
            font=("Segoe UI", 9),
            fg="#262626",
            bg="#e1e1e1",
            activebackground="#c7c7c7",
            activeforeground="#000000",
            relief="flat",
            padx=20,
            pady=5,
            bd=0,
            cursor="hand2",
            command=self.on_btn_click
        )
        self.btn_action.pack(side="right")

    def update_status(self, progress: int, text: str = None, text_color: str = None):
        def _do():
            if progress is not None:
                self.pbar["value"] = progress
            if text:
                self.status_var.set(text)
            if text_color:
                self.status_lbl.configure(fg=text_color)
        self.root.after(0, _do)

    def on_btn_click(self):
        if self.completed:
            self.finish_and_exit()
        else:
            self.cancelled = True
            self.root.destroy()
            sys.exit(0)

    def finish_and_exit(self):
        if self.launch_var.get() and self.dest_exe.exists():
            try:
                subprocess.Popen([str(self.dest_exe)], cwd=str(INSTALL_DIR), creationflags=0x08000000)
                log_install("Launched PrintAgent.exe successfully.")
            except Exception as e:
                log_install(f"Launch error: {e}")
        self.root.destroy()
        sys.exit(0)

    def start_installation(self):
        thread = threading.Thread(target=self._run_install_worker, daemon=True)
        thread.start()

    def _run_install_worker(self):
        try:
            log_install("Installer worker started.")
            self.update_status(10, "Closing existing processes and cleaning cache...")
            kill_existing_processes()

            if self.cancelled:
                return

            INSTALL_DIR.mkdir(parents=True, exist_ok=True)
            api_url = get_api_url_from_settings()

            # Query remote version for display
            try:
                ver_url = f"{api_url.rstrip('/')}/api/agent/release"
                req = urllib.request.Request(ver_url, headers={"User-Agent": "PrintAgentSetup/3.0"})
                ssl_ctx = ssl.create_default_context()
                ssl_ctx.check_hostname = False
                ssl_ctx.verify_mode = ssl.CERT_NONE
                with urllib.request.urlopen(req, timeout=5, context=ssl_ctx) as resp:
                    v_data = json.loads(resp.read().decode('utf-8'))
                    v_str = v_data.get("version")
                    if v_str:
                        self.version_str = v_str
                        self.root.after(0, lambda: self.pub_lbl.configure(text=f"Publisher: Gox Print\nVersion: {self.version_str}"))
            except Exception:
                pass

            if self.cancelled:
                return

            # Download printagent.exe (progress 15% -> 70%)
            self.update_status(15, "Connecting to server...")

            def agent_progress(downloaded, total):
                if self.cancelled or total <= 0:
                    return
                pct = 15 + int((downloaded / total) * 55)
                mb_down = downloaded / (1024 * 1024)
                mb_tot = total / (1024 * 1024)
                self.update_status(pct, f"Installing app package {pct}% ({mb_down:.1f} MB / {mb_tot:.1f} MB)...")

            ok_agent = download_binary(self.dest_exe, api_url, "printagent.exe", progress_cb=agent_progress)
            if not ok_agent:
                if (INSTALL_DIR / "printagent.old.exe").exists() and not self.dest_exe.exists():
                    shutil.copy2(INSTALL_DIR / "printagent.old.exe", self.dest_exe)
                    log_install("Restored previous printagent.old.exe as fallback.")
                else:
                    raise RuntimeError("Failed to download PrintAgent binary from server.")

            if self.cancelled:
                return

            # Download gox_ftp_server.exe (progress 70% -> 82%)
            self.update_status(72, "Downloading background FTP service...")
            ftp_exe = INSTALL_DIR / "gox_ftp_server.exe"

            def ftp_progress(downloaded, total):
                if self.cancelled or total <= 0:
                    return
                pct = 72 + int((downloaded / total) * 10)
                self.update_status(pct, f"Installing background components {pct}%...")

            download_binary(ftp_exe, api_url, "gox_ftp_server.exe", progress_cb=ftp_progress)

            if self.cancelled:
                return

            # Setup GoxDriverService (progress 82% -> 92%)
            self.update_status(85, "Configuring system background service...")
            setup_gox_driver_service(api_url)

            if self.cancelled:
                return

            # Configure settings and startup shortcut (progress 92% -> 100%)
            self.update_status(93, "Configuring settings and automatic startup...")
            configure_settings_json()
            create_startup_shortcut(self.dest_exe)

            # Done!
            self.completed = True
            log_install("Installation completed successfully.")
            self.update_status(100, "✓ PrintAgent has been installed successfully!", "#107c10")

            def _show_finished():
                self.btn_action.configure(
                    text="Finish",
                    bg="#0078d4",
                    fg="#ffffff",
                    activebackground="#0067b8",
                    activeforeground="#ffffff"
                )
                if self.launch_var.get():
                    self.root.after(2200, self.finish_and_exit)

            self.root.after(0, _show_finished)

        except Exception as exc:
            log_install(f"FATAL INSTALLATION ERROR: {exc}")
            self.update_status(None, f"Installation failed: {exc}", "#d13438")
            def _show_error():
                self.btn_action.configure(text="Close", bg="#e1e1e1", fg="#262626")
            self.root.after(0, _show_error)


def main():
    log_install(f"Started PrintAgentSetup. Args: {sys.argv}")
    root = tk.Tk()
    app = InstallerApp(root)
    root.mainloop()

if __name__ == "__main__":
    # Force Administrator Elevation prompt (UAC) before displaying window
    try:
        def is_admin() -> bool:
            try:
                return ctypes.windll.shell32.IsUserAnAdmin() != 0
            except Exception:
                return False

        if not is_admin():
            log_install("Not running as Administrator. Requesting UAC elevation...")
            params = " ".join([f'"{a}"' for a in sys.argv[1:]])
            ret = ctypes.windll.shell32.ShellExecuteW(None, "runas", sys.executable, params, None, 1)
            if int(ret) > 32:
                sys.exit(0)
            else:
                log_install(f"UAC elevation rejected: code {ret}")
    except Exception as e:
        log_install(f"Elevation error: {e}")

    main()
